contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 a, uint256 b) public payable {
        require(address(this).balance >= a);
        c.deposit{value: a}();
        uint256 afterDeposit = address(c).balance;
        bool reverted;
        if (b <= a) {
            c.withdraw(b);
            reverted = false;
        } else {
            try c.withdraw(b) { reverted = false; } catch { reverted = true; }
        }
        uint256 afterWithdraw = address(c).balance;
        if (b <= a) {
            assert(!reverted && afterDeposit >= b && afterWithdraw == afterDeposit - b);
        } else {
            assert(reverted && afterWithdraw == afterDeposit);
        }
    }
    receive() external payable {}
}

